export type MonsterColorSpriteData = readonly (readonly [sprite: string, poses: readonly string[], blob: string])[]

/**
 * Per-sprite palette-indexed frames packed into one zlib-compressed blob:
 * u16be colorCount, colorCount * 3 bytes RGB (opaque colors in lexicographic
 * order), then 256 bytes of palette indices per pose in `poses` order.
 * Pixel index 0 means transparent; positive indices address the palette
 * starting at 1. Decode through `src/data/monster-frame-catalog.ts`.
 */
